<script setup>
import { ref } from 'vue'
import { call } from 'frappe-ui'

const loading = ref(false)
const error = ref('')
const results = ref([])
const farfalleUrl = ref('')
const company = ref('')
const domain = ref('')
const intel = ref(null)

function guessFarfalleBase() {
  // Heuristic: same host on port 8000 or env override via window.FARFALLE_BASE
  if (window.FARFALLE_BASE) return String(window.FARFALLE_BASE)
  const { protocol, hostname } = window.location
  return `${protocol}//${hostname}:8000`
}

async function analyze() {
  loading.value = true
  error.value = ''
  intel.value = null
  try {
    const base = farfalleUrl.value || guessFarfalleBase()
    const resp = await fetch(`${base}/intel/enrich_lead`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ company: company.value, domain: domain.value })
    })
    if (!resp.ok) throw new Error(`Intel failed (${resp.status})`)
    intel.value = await resp.json()
  } catch (e) {
    error.value = e?.message || 'Failed'
  } finally {
    loading.value = false
  }
}

async function demoListOpenLeads() {
  loading.value = true
  error.value = ''
  results.value = []
  try {
    const res = await call('crm.api.doc.get_data', {
      doctype: 'CRM Lead',
      filters: { converted: ['=', 0] },
      order_by: 'modified desc',
      page_length: 10
    })
    results.value = res.data?.data || []
  } catch (e) {
    error.value = e?.message || 'Failed'
  } finally {
    loading.value = false
  }
}

async function saveToCRM() {
  if (!intel.value) return
  
  loading.value = true
  error.value = ''
  try {
    // Create a CRM Note with the intelligence summary
    const noteContent = `# Intelligence Analysis: ${intel.value.company}

## Summary
${intel.value.summary.map(s => `- ${s}`).join('\n')}

## Key Insights
${intel.value.key_insights.map(i => `- ${i}`).join('\n')}

## Detailed Analysis
${intel.value.results.map(r => `### ${r.question}\n${r.answer}\n\n**Sources:**\n${r.sources.map(s => `- [${s.title}](${s.url})`).join('\n')}`).join('\n\n')}

---
*Generated by AI Copilot on ${new Date().toLocaleString()}*`

    const res = await call('frappe.client.insert', {
      doc: {
        doctype: 'FCRM Note',
        title: `AI Intelligence: ${intel.value.company}`,
        content: noteContent,
        reference_doctype: 'CRM Lead',
        reference_name: company.value
      }
    })
    
    // Show success message
    alert(`Intelligence saved to CRM Note: ${res.data.name}`)
    
  } catch (e) {
    error.value = e?.message || 'Failed to save to CRM'
  } finally {
    loading.value = false
  }
}
</script>

<template>
  <div class="p-4 space-y-4">
    <div class="flex items-center justify-between">
      <h1 class="text-xl font-semibold">AI Copilot</h1>
      <button class="btn btn-primary" @click="demoListOpenLeads" :disabled="loading">
        {{ loading ? 'Loading…' : 'Demo: List Top 10 Open Leads' }}
      </button>
    </div>

    <div v-if="error" class="text-red-600">{{ error }}</div>

    <div class="grid grid-cols-1 md:grid-cols-3 gap-4">
      <div class="space-y-2 p-3 border rounded">
        <div class="font-medium">Analyze Company</div>
        <label class="block text-sm">Farfalle URL (optional)</label>
        <input class="input" v-model="farfalleUrl" placeholder="http://localhost:8000" />
        <label class="block text-sm">Company</label>
        <input class="input" v-model="company" placeholder="Abbey Capital" />
        <label class="block text-sm">Domain (optional)</label>
        <input class="input" v-model="domain" placeholder="abbeycapital.com" />
        <button class="btn" @click="analyze" :disabled="loading || !company">{{ loading ? 'Analyzing…' : 'Analyze' }}</button>
      </div>
      <div class="md:col-span-2 p-3 border rounded" v-if="intel">
        <div class="flex items-center justify-between mb-2">
          <div class="font-medium">Summary</div>
          <button class="btn btn-sm" @click="saveToCRM" :disabled="loading">
            {{ loading ? 'Saving...' : 'Save to CRM' }}
          </button>
        </div>
        <ul class="list-disc ml-5">
          <li v-for="(b,i) in intel.summary" :key="i">{{ b }}</li>
        </ul>
        
        <div class="mt-4 font-medium">Key Insights</div>
        <ul class="list-disc ml-5">
          <li v-for="(i,idx) in intel.key_insights" :key="idx">{{ i }}</li>
        </ul>
        
        <div class="mt-4 font-medium">Decision Makers</div>
        <div v-for="(r,idx) in intel.results" :key="idx" v-if="r.extracted_people">
          <div v-for="(p,pidx) in r.extracted_people" :key="pidx" class="text-sm p-2 bg-gray-50 rounded mb-1">
            <strong>{{ p.name }}</strong> - {{ p.title }}
            <a v-if="p.source_url" :href="p.source_url" target="_blank" class="text-blue-600 hover:underline ml-2">View Profile</a>
          </div>
        </div>
        
        <div class="mt-4 font-medium">Sources</div>
        <ul class="list-disc ml-5">
          <li v-for="(s,i) in (intel.results?.flatMap(r=>r.sources)||[])" :key="i">
            <a class="text-blue-600 hover:underline" :href="s.url" target="_blank">{{ s.title }}</a>
          </li>
        </ul>
      </div>
    </div>

    <div v-if="results.length" class="space-y-2">
      <div v-for="r in results" :key="r.name" class="p-3 rounded border">
        <a class="text-blue-600 hover:underline" :href="`/crm/leads/${r.name}`">{{ r.name }}</a>
        <div class="text-sm text-gray-600">Last Modified: {{ r.modified }}</div>
      </div>
    </div>

    <div class="mt-6">
      <div class="mb-2 text-sm text-gray-600">Chat (embed Farfalle webchat here):</div>
      <div class="border rounded h-96 flex items-center justify-center text-gray-500">
        Coming soon: Farfalle webchat iframe / component
      </div>
    </div>
  </div>
</template>

<style scoped>
.btn { @apply px-3 py-2 rounded bg-blue-600 text-white hover:bg-blue-700; }
.btn-sm { @apply px-2 py-1 text-sm; }
.input { @apply w-full px-3 py-2 border rounded; }
</style>


